def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if len(alive) == 0:
        base = DAILY_SALARY * 0.25
        if hp <= 2 or no_water >= 2:
            base = DAILY_SALARY * 0.6
        return float(min(budget, base))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    broke_count = 0
    pressure_score = 0.0

    for oid, opp in alive:
        obudget = opp.get('budget', 0)
        ohp = opp.get('hp', 0)
        onw = opp.get('no_water_days', 0)
        if obudget < DAILY_SALARY * 0.8:
            broke_count += 1
        if obudget > DAILY_SALARY * 2.0:
            rich_count += 1
        if ohp <= 3 or onw >= 2:
            desperate_count += 1

        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(pbid)
            if pbid >= 150:
                pressure_score += 2.2
            elif pbid >= 110:
                pressure_score += 1.5
            elif pbid >= 70:
                pressure_score += 0.9
            else:
                pressure_score += 0.3
        if prev.get('status') == 'error':
            pressure_score -= 0.5

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 70.0
    max_prev = max(prev_bids) if prev_bids else 70.0

    supply_tight = (supply <= 17)
    supply_loose = (supply >= 22)

    urgency = 0.0
    if hp <= 2:
        urgency += 3.0
    elif hp <= 4:
        urgency += 1.8
    if no_water >= 2:
        urgency += 3.0
    elif no_water >= 1:
        urgency += 1.2
    if day >= 8:
        urgency += 0.6
    if supply_tight:
        urgency += 1.2
    elif supply_loose:
        urgency -= 0.5

    market_heat = pressure_score / max(1, len(alive))
    if desperate_count >= 2:
        market_heat += 0.8
    if broke_count >= 2:
        market_heat -= 0.7
    if rich_count >= 2:
        market_heat += 0.4

    if urgency < 1.0 and supply_loose:
        bid = DAILY_SALARY * 0.28
    elif urgency < 2.0 and market_heat > 1.4:
        bid = DAILY_SALARY * 0.35
    elif urgency >= 4.0:
        bid = max(DAILY_SALARY * 1.35, min(max_prev + 6.0, DAILY_SALARY * 2.2))
    elif urgency >= 2.5:
        bid = max(DAILY_SALARY * 0.95, min(avg_prev + 4.0, DAILY_SALARY * 1.7))
    else:
        if market_heat > 1.8:
            bid = DAILY_SALARY * 0.45
        elif market_heat > 1.1:
            bid = DAILY_SALARY * 0.62
        else:
            bid = DAILY_SALARY * 0.78

    if supply_tight and urgency >= 2.0:
        bid += 12.0
    if supply_loose and urgency < 2.0:
        bid -= 8.0

    if budget < DAILY_SALARY * 1.2 and urgency < 3.0:
        bid = min(bid, budget * 0.55)
    elif budget < DAILY_SALARY * 0.8:
        bid = min(bid, budget * 0.8)

    if hp >= 7 and no_water == 0 and market_heat > 1.6 and day <= 6:
        bid = min(bid, DAILY_SALARY * 0.4)

    min_probe = 6.0 if urgency < 2.0 else 18.0
    bid = max(min_probe, bid)
    bid = min(bid, budget)
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_hp_after = []
    prev_budget_after = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
        if prev:
            if 'hp_after' in prev:
                try:
                    prev_hp_after.append(float(prev.get('hp_after')))
                except Exception:
                    pass
            if 'budget_after' in prev:
                try:
                    prev_budget_after.append(float(prev.get('budget_after')))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Determine aggressiveness: if others were spending heavily, we bid enough to avoid losing.
    # Use our hp/no-water days to decide urgency.
    urgency = 0
    if my_hp <= 2.0:
        urgency += 2
    elif my_hp <= 4.0:
        urgency += 1
    if my_no_water_days >= 2:
        urgency += 1

    # Supply pressure: with limited supply, higher bids are more valuable.
    # supply is between 15 and 25; normalize.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Baseline bid levels
    # If others were bidding very high yesterday, we match a fraction to secure.
    if highest_prev_bid >= DAILY_SALARY * 1.3:
        base = max(DAILY_SALARY * 0.75, avg_prev_bid * 0.85)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        base = max(DAILY_SALARY * 0.6, avg_prev_bid * 0.7)
    else:
        base = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.55)

    # Adjust with urgency and supply pressure.
    # When supply is low, we increase bids to prevent starvation.
    base *= (1.0 + 0.35 * (1.0 - supply_norm))
    base *= (1.0 + 0.25 * urgency)

    # If we suspect opponents overextended (some had 0 budget yesterday), we can slightly undercut.
    undercut = 1.0
    if prev_budget_after:
        # If many had low budgets after, they might bid less today.
        low_budget_count = sum(1 for b in prev_budget_after if b <= 1e-6)
        if low_budget_count >= max(1, len(prev_budget_after) // 3):
            undercut = 0.9

    target = base * undercut

    # Convert to feasible bid: cannot exceed our budget.
    bid = min(my_budget, target)

    # Safety: if we are in critical hp state, ensure a higher bid floor.
    if my_hp <= 2.0:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.95))
    elif my_no_water_days >= 3:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.8))

    # If we are healthy and opponents were not bidding hard, conserve.
    if my_hp >= 7.0 and highest_prev_bid < DAILY_SALARY * 0.85:
        bid = min(bid, my_budget, DAILY_SALARY * 0.55)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev = max(yesterday_bids) if yesterday_bids else 50.0

    if supply <= 18:
        bid = min(my_status['budget'], max_prev * 1.1)
    elif my_status['hp'] < 5:
        bid = min(my_status['budget'], DAILY_SALARY * 0.8)
    else:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.4, max_prev * 0.9))

    return float(max(0, bid))
